// One picture bench run end to end (#340), at the bench-run seam: a code only run on the invented Kestrel Row Bike
// Workshop plan, brief and kit, through the shared bench run loop, with a model door that fails the test if anything
// calls it. The run cuts the owner photos (generated by code) for any-real and portrait frames, draws initials for a
// person with no portrait, hides, copies twins, returns frames the kit cannot take, lists the painted behind picture
// in siteSettings, stores every file by its hash with a row per file, and its manifest passes the picture check.
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { after, before, beforeEach, test } from 'node:test'
import { filesOf, readRun } from '../src/site-pictures/bench-store.js'
import { checkPictures } from '../src/site-pictures/picture-check/check-pictures.js'
import { scriptedModel } from './_agent-over-door-fake.mjs'
import { fileDb } from './_db.mjs'
import {
  brief,
  contentMap,
  drain,
  kit,
  kitIndex,
  plan,
  sizeOf,
  startRun,
  storeDir
} from './_site-pictures-bench.mjs'
import { assignPickerDoor, drainPicker, reply, SECRET } from './_site-pictures-picker.mjs'

const db = fileDb()
before(db.open)
beforeEach(db.reset)
after(db.close)

const opts = { skip: process.env.TEST_DATABASE_URL ? false : 'set TEST_DATABASE_URL' }
const kits = kitIndex()
after(kits.done)
const store = storeDir()
after(store.done)
const where = { index: kits.index, dir: store.dir }

const sha = (bytes) => createHash('sha256').update(bytes).digest('hex')
const byFrame = (manifest) => new Map([...manifest.frames, ...manifest.siteSettings].map((e) => [e.frame, e]))

test(
  'a code only run writes files and a site-pictures/1 manifest that pass the picture check',
  opts,
  async () => {
    const { pool } = db
    const started = await startRun(pool, where)
    await drain(pool, where)

    const run = await readRun(pool, started.id)
    assert.equal(run.status, 'succeeded', run.error)
    assert.deepEqual(
      run.rounds.map((r) => [r.round, r.state, r.failureList]),
      [[0, 'checked', '']]
    )
    assert.equal(run.standingFailures, null)
    const manifest = run.rounds[0].pictures
    assert.equal(manifest.version, 'site-pictures/1')
    assert.equal(run.rounds[0].checkResult.summary.fail, 0)
    const e = byFrame(manifest)

    // Any-real frames: owner photos, the hero takes the photo of its own offering; never drawn.
    assert.equal(e.get('block-2.0').source, 'owner-photo')
    assert.equal(e.get('block-2.0').asset, 'p-workbench')
    assert.equal(e.get('block-6.1').asset, 'p-wheels')
    for (const entry of manifest.frames) assert.ok(!['drawn', 'owner-photo-extended'].includes(entry.source))
    // Never a photo with lettering, a blurry one, or a video.
    const used = new Set(manifest.frames.map((x) => x.asset).filter(Boolean))
    for (const out of ['p-sign', 'p-blurry', 'v-tour']) assert.ok(!used.has(out), out)
    // No photo twice on the home page.
    const home = ['block-2.0', 'block-3.1', 'block-3.2', 'block-3.3', 'block-3.4', 'block-4.1', 'block-6.1']
    const homeAssets = home.map((f) => e.get(f)?.asset).filter(Boolean)
    assert.equal(new Set(homeAssets).size, homeAssets.length)
    // The gallery ran out of fitting photos: what is left is hidden, which the kit allows.
    assert.ok(['block-3.1', 'block-3.2', 'block-3.3', 'block-3.4'].some((f) => e.get(f).source === 'hide'))
    // Person frames: the confirmed portrait, and initials in the template accent for the person without one.
    assert.equal(e.get('block-4.1').source, 'owner-photo')
    assert.equal(e.get('block-4.1').asset, 'p-owner')
    assert.deepEqual([e.get('block-4.2').source, e.get('block-4.2').letters], ['initials', 'TB'])
    assert.equal(e.get('block-4.2').recolourable, true)
    // Twins: the plan's sameAs and the kit's twin copy their source's file.
    assert.deepEqual([e.get('block-5.2').source, e.get('block-5.2').twinOf], ['twin', 'block-5.1'])
    assert.equal(e.get('block-5.2').sha256, e.get('block-5.1').sha256)
    assert.deepEqual(
      [e.get('block-6.9').source, e.get('block-6.9').sha256],
      ['twin', e.get('block-6.1').sha256]
    )
    // Not writable: returned to the planner, except the picture painted behind blocks, listed in siteSettings.
    assert.deepEqual(
      manifest.returns.map((r) => r.frame),
      ['block-8.1']
    )
    assert.deepEqual(
      manifest.siteSettings.map((s) => [s.frame, s.writeDoor]),
      [['block-7.picture-1', 'none']]
    )
    assert.deepEqual(manifest.pending, [])
    // Cost and time per role are recorded; a code only run spends nothing and reads no balance.
    assert.deepEqual(manifest.cost, { code: 0 })
    assert.ok(Number.isInteger(manifest.timing.code) && manifest.timing.code >= 0)
    assert.equal(run.costUsd, 0)
    assert.equal(run.totals.calls, 0)
    assert.equal(run.balance, null)
    assert.ok(run.finishedAt && Date.parse(run.finishedAt) >= Date.parse(run.createdAt))
    assert.match(manifest.fingerprint.planSha256, /^[0-9a-f]{64}$/)
    assert.equal(manifest.fingerprint.kit, 'tracy-template-kit/2 demo-bikes/j6/1.0.0')

    // Every placed file is on disk under its hash, of the size and hash the manifest says, with one row per file.
    const rows = await filesOf(pool, started.id)
    const placed = [...manifest.frames, ...manifest.siteSettings].filter((x) => x.file)
    assert.deepEqual(new Set(rows.map((r) => r.sha256)), new Set(placed.map((x) => x.sha256)))
    const files = {}
    for (const row of rows) {
      const bytes = await readFile(path.join(store.dir, row.path))
      assert.equal(sha(bytes), row.sha256)
      assert.equal(bytes.length, row.bytes)
      assert.equal(row.costUsd, 0)
      const size = await sizeOf(bytes)
      assert.deepEqual([size.width, size.height], [row.width, row.height])
      files[`files/${row.path}`] = { sha256: row.sha256, ...size }
    }
    for (const x of placed) {
      const k = kit()
        .blocks.flatMap((b) => b.frames)
        .find((f) => f.id === x.frame)
      assert.ok(x.width >= k.width && x.height >= k.height, `${x.frame} covers its display box`)
      const demo = contentMap().slots.find((s) => s.key === x.frame.replace(/^block-/, 'module-'))?.fit.source
      if (demo) assert.ok(Math.abs(x.width / x.height - demo.width / demo.height) <= 0.02, x.frame)
      assert.equal(x.sitePath, `images/tracy-content/${x.sha256}.jpg`)
    }
    // The same check, run again here on the files read back from disk.
    const again = checkPictures({
      pictures: manifest,
      plan: plan(),
      kit: { ...kit(), contentMap: contentMap() },
      brief: brief(),
      files
    })
    assert.equal(again.summary.fail, 0, JSON.stringify(again.rules.filter((r) => r.status === 'fail')))
  }
)

test(
  'specific, icon and cut-out frames are left as pending entries, never as demo pictures',
  opts,
  async () => {
    const { pool } = db
    // The specific frame goes to the picker (#342), which finds no fitting photo: it waits for the drawer.
    await assignPickerDoor(pool)
    const started = await startRun(pool, where, { plan: plan({ later: true }), secret: SECRET })
    const model = scriptedModel([
      reply({
        picks: [{ frame: 'block-9.0', photo: 'none', reason: 'no photo shows the owner fitting a tyre' }]
      })
    ])
    await drainPicker(pool, { ...where, fetchImpl: model.fetchImpl })

    const run = await readRun(pool, started.id)
    assert.equal(run.status, 'succeeded', run.error)
    const manifest = run.rounds[0].pictures
    assert.deepEqual(
      manifest.pending.map((p) => [p.frame, p.waitsFor]),
      [
        ['block-9.1', 'icons'],
        ['block-9.2', 'cut-out'],
        ['block-9.0', 'drawer']
      ]
    )
    const placedFrames = new Set([...manifest.frames, ...manifest.siteSettings].map((x) => x.frame))
    for (const f of ['block-9.0', 'block-9.1', 'block-9.2']) assert.ok(!placedFrames.has(f), f)
    // The picture check counts the pending frames as unfilled, and nothing else fails; none of them is the picker's
    // to fix, so no fix round runs and the failures are kept on the round's check result.
    const failing = run.rounds[0].checkResult.rules.filter((r) => r.status === 'fail')
    assert.deepEqual(
      failing.map((r) => r.id),
      ['P01']
    )
    assert.deepEqual(failing[0].failures.map((f) => f.where).sort(), ['block-9.0', 'block-9.1', 'block-9.2'])
    assert.equal(model.requests.length, 1)
    assert.equal(run.rounds.length, 1)
    assert.match(run.rounds[0].checkResult.notForPicker, /block-9\.0/)
  }
)

test('the inputs of a run are frozen once it is stored', opts, async () => {
  const { pool } = db
  const started = await startRun(pool, where)
  for (const column of ['plan', 'brief', 'kit', 'photo_source', 'prompts', 'door', 'harness'])
    await assert.rejects(
      pool.query(`update site_picture_run set ${column} = '{"changed": true}'::jsonb where id = $1`, [
        started.id
      ]),
      /site picture run input is immutable/
    )
  await assert.rejects(
    pool.query(`update site_picture_run set checker_version = 'x' where id = $1`, [started.id]),
    /immutable/
  )
})
